const inflightGets = new Map<string, InflightGet>();
let sessionChangeDepth = 0;

/** Fence HTTP coalescing, not just query caches, across uncertain cookie changes. */
export function beginApiSessionChange(): () => void {
  sessionChangeDepth += 1;
  inflightGets.clear();
  let finished = false;
  return () => {
    if (finished) return;
    finished = true;
    sessionChangeDepth -= 1;
    // A failed/lost auth response may still have installed a new cookie.
    // Never restore the detached session's requests.
    inflightGets.clear();
  };
}

